# 导入必要的库
import pygame
import random
from collections import deque
from typing import Deque, List, Tuple
import pickle

# 初始化 Pygame
pygame.init()

# 设置屏幕尺寸
SCREEN_WIDTH, SCREEN_HEIGHT = 800, 600
screen = pygame.display.set_mode((SCREEN_WIDTH, SCREEN_HEIGHT))
pygame.display.set_caption("Snake Game")

# 颜色定义
WHITE = (255, 255, 255)
BLACK = (0, 0, 0)
GREEN = (0, 255, 0)
RED = (255, 0, 0)
BLUE = (0, 0, 255)

# 游戏状态常量
STATE_MENU = "MENU"
STATE_PLAYING = "PLAYING"
STATE_PAUSED = "PAUSED"
STATE_GAME_OVER = "GAME_OVER"

# InputHandler 模块
class PyGameInputHandler:
    """
    将 Pygame 事件转换为游戏引擎命令。
    支持即时命令（如退出、开始）和方向命令队列（避免快速按键丢失）。
    """
    CMD_QUIT = 'QUIT'
    CMD_START = 'START_GAME'
    CMD_RESTART = 'RESTART_GAME'
    CMD_PAUSE_TOGGLE = 'PAUSE_TOGGLE'
    CMD_UP = 'MOVE_UP'
    CMD_DOWN = 'MOVE_DOWN'
    CMD_LEFT = 'MOVE_LEFT'
    CMD_RIGHT = 'MOVE_RIGHT'

    def __init__(self):
        self._direction_command_queue: Deque[str] = deque(maxlen=2)  # 最多缓存2个方向指令
        self._current_pressed_directions = set()

    def process_events(self) -> List[str]:
        non_direction_commands = []
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                non_direction_commands.append(self.CMD_QUIT)
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_RETURN:
                    non_direction_commands.append(self.CMD_START)
                elif event.key == pygame.K_r:
                    non_direction_commands.append(self.CMD_RESTART)
                elif event.key == pygame.K_p:
                    non_direction_commands.append(self.CMD_PAUSE_TOGGLE)
                elif event.key == pygame.K_ESCAPE:
                    non_direction_commands.append(self.CMD_QUIT)

                direction_cmd = self._key_to_direction_command(event.key)
                if direction_cmd and direction_cmd not in self._current_pressed_directions:
                    self._direction_command_queue.append(direction_cmd)
                    self._current_pressed_directions.add(direction_cmd)

            elif event.type == pygame.KEYUP:
                direction_cmd = self._key_to_direction_command(event.key)
                if direction_cmd in self._current_pressed_directions:
                    self._current_pressed_directions.remove(direction_cmd)

        if not self._direction_command_queue and self._current_pressed_directions:
            for cmd in self._current_pressed_directions:
                self._direction_command_queue.append(cmd)
                break

        return non_direction_commands

    def get_next_direction_command(self) -> str:
        if self._direction_command_queue:
            return self._direction_command_queue.popleft()
        return None

    def _key_to_direction_command(self, key) -> str:
        mapping = {
            pygame.K_UP: self.CMD_UP,
            pygame.K_DOWN: self.CMD_DOWN,
            pygame.K_LEFT: self.CMD_LEFT,
            pygame.K_RIGHT: self.CMD_RIGHT,
            pygame.K_w: self.CMD_UP,
            pygame.K_s: self.CMD_DOWN,
            pygame.K_a: self.CMD_LEFT,
            pygame.K_d: self.CMD_RIGHT,
        }
        return mapping.get(key, None)

    def clear_direction_queue(self):
        self._direction_command_queue.clear()
        self._current_pressed_directions.clear()

# 实体类
class Snake:
    def __init__(self, start_pos: Tuple[int, int] = (5, 5), start_length: int = 3):
        self._body: List[Tuple[int, int]] = [start_pos]
        for i in range(1, start_length):
            self._body.append((start_pos[0] - i, start_pos[1]))
        self._direction: Tuple[int, int] = (1, 0)
        self._next_direction: Tuple[int, int] = (1, 0)
        self._grow_pending = False

    @property
    def body(self) -> List[Tuple[int, int]]:
        return self._body.copy()

    @property
    def head(self) -> Tuple[int, int]:
        return self._body[0]

    def set_direction(self, new_direction: str):
        direction_map = {
            'MOVE_UP': (0, -1),
            'MOVE_DOWN': (0, 1),
            'MOVE_LEFT': (-1, 0),
            'MOVE_RIGHT': (1, 0),
        }
        if new_direction in direction_map:
            new_vec = direction_map[new_direction]
            if (new_vec[0] * -1, new_vec[1] * -1) != self._direction:
                self._next_direction = new_vec

    def update(self):
        self._direction = self._next_direction
        new_head = (self.head[0] + self._direction[0], self.head[1] + self._direction[1])
        self._body.insert(0, new_head)
        if not self._grow_pending:
            self._body.pop()
        else:
            self._grow_pending = False

    def grow(self):
        self._grow_pending = True

    def is_collision(self) -> bool:
        head = self.head
        return head in self._body[1:] or head[0] < 0 or head[0] >= SCREEN_WIDTH or head[1] < 0 or head[1] >= SCREEN_HEIGHT

class Food:
    def __init__(self):
        self.position = (random.randint(0, SCREEN_WIDTH // 10) * 10, random.randint(0, SCREEN_HEIGHT // 10) * 10)

    def generate(self, snake_positions: List[Tuple[int, int]]):
        while True:
            new_position = (random.randint(0, SCREEN_WIDTH // 10) * 10, random.randint(0, SCREEN_HEIGHT // 10) * 10)
            if new_position not in snake_positions:
                self.position = new_position
                break

    def get_position(self) -> Tuple[int, int]:
        return self.position

# Renderer 模块
class PyGameRenderer:
    def draw(self, state_data: dict):
        screen.fill(BLACK)
        for pos in state_data["snake_positions"]:
            pygame.draw.rect(screen, GREEN, (pos[0], pos[1], 10, 10))
        pygame.draw.rect(screen, RED, (state_data["food_position"][0], state_data["food_position"][1], 10, 10))

        font = pygame.font.Font(None, 36)
        text = font.render(f"Score: {state_data['score']}", True, WHITE)
        screen.blit(text, (10, 10))

        if state_data["state"] == STATE_MENU:
            self._draw_menu()
        elif state_data["state"] == STATE_PAUSED:
            self._draw_paused()
        elif state_data["state"] == STATE_GAME_OVER:
            self._draw_game_over(state_data["high_score"])

        pygame.display.flip()

    def _draw_menu(self):
        font = pygame.font.Font(None, 72)
        text = font.render("Press Enter to Start", True, BLUE)
        screen.blit(text, (SCREEN_WIDTH // 2 - text.get_width() // 2, SCREEN_HEIGHT // 2 - text.get_height() // 2))

    def _draw_paused(self):
        font = pygame.font.Font(None, 72)
        text = font.render("Paused", True, BLUE)
        screen.blit(text, (SCREEN_WIDTH // 2 - text.get_width() // 2, SCREEN_HEIGHT // 2 - text.get_height() // 2))

    def _draw_game_over(self, high_score: int):
        font = pygame.font.Font(None, 72)
        text = font.render(f"Game Over! High Score: {high_score}", True, BLUE)
        screen.blit(text, (SCREEN_WIDTH // 2 - text.get_width() // 2, SCREEN_HEIGHT // 2 - text.get_height() // 2))

# GameEngine 模块
class GameEngine:
    def __init__(self, renderer, input_handler):
        self.state = STATE_MENU
        self.renderer = renderer
        self.input_handler = input_handler
        self.snake = Snake()
        self.food = Food()
        self.score = 0
        self.high_score = self.load_high_score()

    def update(self):
        user_input = self.input_handler.get_next_direction_command()
        if self.state == STATE_MENU and user_input == PyGameInputHandler.CMD_START:
            self.state = STATE_PLAYING
        elif self.state == STATE_PLAYING:
            self._update_game_logic(user_input)
        elif self.state == STATE_PAUSED and user_input == PyGameInputHandler.CMD_PAUSE_TOGGLE:
            self.state = STATE_PLAYING
        elif self.state == STATE_PLAYING and user_input == PyGameInputHandler.CMD_PAUSE_TOGGLE:
            self.state = STATE_PAUSED
        elif self.state == STATE_GAME_OVER and user_input == PyGameInputHandler.CMD_RESTART:
            self.state = STATE_MENU
            self.reset_game()

    def render(self):
        state_data = self._get_state_data()
        self.renderer.draw(state_data)

    def _update_game_logic(self, user_input):
        if user_input:
            self.snake.set_direction(user_input)
        self.snake.update()
        if self.snake.head == self.food.get_position():
            self.snake.grow()
            self.food.generate(self.snake.body)
            self.score += 1
        if self.snake.is_collision():
            self.state = STATE_GAME_OVER
            self.save_high_score()

    def _get_state_data(self):
        return {
            "snake_positions": self.snake.body,
            "food_position": self.food.get_position(),
            "score": self.score,
            "state": self.state,
            "high_score": self.high_score
        }

    def save_high_score(self):
        if self.score > self.high_score:
            self.high_score = self.score
            with open("high_score.pkl", "wb") as f:
                pickle.dump(self.high_score, f)

    def load_high_score(self):
        try:
            with open("high_score.pkl", "rb") as f:
                return pickle.load(f)
        except FileNotFoundError:
            return 0

    def reset_game(self):
        self.snake = Snake()
        self.food = Food()
        self.score = 0

# 主函数
def main():
    clock = pygame.time.Clock()
    input_handler = PyGameInputHandler()
    renderer = PyGameRenderer()
    game_engine = GameEngine(renderer, input_handler)

    running = True
    while running:
        non_direction_commands = input_handler.process_events()
        for cmd in non_direction_commands:
            if cmd == PyGameInputHandler.CMD_QUIT:
                running = False
            elif cmd == PyGameInputHandler.CMD_RESTART:
                input_handler.clear_direction_queue()
                game_engine = GameEngine(renderer, input_handler)

        game_engine.update()
        game_engine.render()

        clock.tick(60)

    pygame.quit()

if __name__ == "__main__":
    main()
